actions.script:
const sales=ec.resource.script('component://mr-pass/screen/Sales/Sales.js')
state=sales.param('state') === 'open' ? 'open' : 'all'
reference=(sales.param('reference') || '').slice(0,60)
cursor=sales.param('cursor')
const found=siteInfo.authenticated ? sales.portal.attempt('findSalesOrders',{siteId:resolvedSiteId,state,reference,cursor}) : {result:null}
view=found.result || null
const filters={state:state === 'all' ? null : state,reference:reference || null}
nextHref=view?.nextCursor ? publicPath + sales.query(Object.assign({},filters,{cursor:view.nextCursor})) : null
firstHref=cursor ? publicPath + sales.query(filters) : null
failure=found.error || null
